#define write2Byte(ADDR, VAL) do {\
                if (!MHal_XC_CheckMuteStatusByRegister(MAIN_WINDOW) || !MHal_XC_CheckMuteStatusByRegister(SUB_WINDOW))    \
                {                                                       \
                    KApi_XC_MLoad_WriteCmd(E_CLIENT_MAIN_HDR, ADDR, ((VAL) & 0xFFFF), 0xFFFF);  \
                }                                                                               \
                else                                                                       \
                {                                                                   \
                    MApi_GFLIP_XC_W2BYTE( ADDR, VAL );                              \
                }                                                                   \
            } while(0)
#define write2ByteMask(ADDR,MASK, VAL) do {\
                if (!MHal_XC_CheckMuteStatusByRegister(MAIN_WINDOW) || !MHal_XC_CheckMuteStatusByRegister(SUB_WINDOW))    \
                {                                                       \
                    KApi_XC_MLoad_WriteCmd(E_CLIENT_MAIN_HDR, ADDR, ((VAL) & 0xFFFF), MASK);  \
                }                                                                               \
                else                                                                       \
                {                                                                   \
                    MApi_GFLIP_XC_W2BYTEMSK(ADDR,  VAL, MASK);                              \
                }                                                                   \
            } while(0)
#define writeByteMask(ADDR,MASK, VAL) do {\
                if (!MHal_XC_CheckMuteStatusByRegister(MAIN_WINDOW) || !MHal_XC_CheckMuteStatusByRegister(SUB_WINDOW))    \
                {                                                       \
                    KApi_XC_MLoad_WriteCmd(E_CLIENT_MAIN_HDR, (ADDR) - (ADDR % 2), ((VAL) & 0xFF) << (8 * (ADDR % 2)), ((MASK) & 0xFF) << (8 * (ADDR % 2)));  \
                }                                                                               \
                else                                                                       \
                {                                                                   \
                    msWriteByteMask(ADDR,VAL,MASK);                              \
                }                                                                   \
            } while(0)
#define write4Bytes(ADDR, VAL) do {\
                if (!MHal_XC_CheckMuteStatusByRegister(MAIN_WINDOW) || !MHal_XC_CheckMuteStatusByRegister(SUB_WINDOW))    \
                {                                                       \
                    KApi_XC_MLoad_WriteCmd(E_CLIENT_MAIN_HDR, ADDR, ((VAL) & 0xFFFF), 0xFFFF);          \
                    KApi_XC_MLoad_WriteCmd(E_CLIENT_MAIN_HDR, ((ADDR) + 2), (((VAL)>>16) & 0xFFFF), 0xFFFF);  \
                }                                                                               \
                else                                                                       \
                {                                                                   \
                    write2Byte( (ADDR), (VAL & 0x0000FFFF) );                       \
                    write2Byte( (ADDR+2), (VAL>>16));                              \
                }                                                                   \
            } while(0)
#define write2Bytes write2Byte

#else
#define write2Byte(ADDR, VAL) MApi_GFLIP_XC_W2BYTE( ADDR, VAL )
#define write2ByteMask(ADDR,MASK, VAL)  MApi_GFLIP_XC_W2BYTEMSK(ADDR,  VAL, MASK)
#define writeByteMask(ADDR,MASK, VAL) msWriteByteMask(ADDR,VAL,MASK)
#define write4Bytes(ADDR, VAL) write2Byte( (ADDR), (VAL & 0x0000FFFF) ); write2Byte( (ADDR+2), (VAL>>16))
#define write2Bytes write2Byte
#endif
