               //printf("0x%x   write 0x%x\n", (ADDR), (VAL));
#define write4Bytes(ADDR, VAL) write2Byte( (ADDR), (VAL & 0x0000FFFF) ); write2Byte( (ADDR+2), (VAL>>16))
#define write2Bytes write2Byte

#define writeByteMask(ADDR,MASK, VAL)  //fprintf(fi,"wriu %0#x %0#x\n", 0x102F00 , ((ADDR) & 0x0000FF00)>>8 ); \
                                     //fprintf(fi,"wriu -b %0#x %0#x %0#x\n", 0x102F00 | ((ADDR) & 0x000000FF) ,(MASK) ,(VAL) ); \
